import React, { useState, useEffect } from 'react';
import { ratingService } from '../../../services/ratingService';
import { departmentService } from '../../../services/departmentService';
import { categoryService } from '../../../services/categoryService';
import { cycleService } from '../../../services/cycleService';
import { Department, Category, Cycle } from '../../../types';
import { toast } from 'react-hot-toast';
import { ChevronDown, ChevronRight, FileSpreadsheet, Filter } from 'lucide-react';
import './RatingsReportNew.css';

const HIDDEN_USERNAMES = new Set([
  'testUser', 'test_one', 'TEST', 'new_test', 'ABC', 'test_new_updated',
  'Mubashir', 'Test3', 'ABC_TEST', 'testadmin'
]);

const HIDDEN_EMAILS = new Set([
  'test@admin.com', 'test@neduet.edu.pk', 'mmubashirkhan@gmail.com'
]);

interface YearlyValue {
  year: number;
  actualValue: number;
  projectedValue: number;
  textValue: string | null;
}

interface RatingRow {
  parameterName: string;
  categoryId: number;
  categoryName: string;
  userName: string;
  userEmail: string;
  departmentId: number;
  departmentName: string;
  yearlyValues: YearlyValue[];
  createdAt: string;
  updatedAt: string;
}

const RatingsReportNew: React.FC = () => {
  // Filter states
  const [cycles, setCycles] = useState<Cycle[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);

  const [selectedCycle, setSelectedCycle] = useState<Cycle | null>(null);
  const [selectedDept, setSelectedDept] = useState<Department | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);

  // Data states
  const [ratings, setRatings] = useState<RatingRow[]>([]);
  const [expandedRows, setExpandedRows] = useState<Set<number>>(new Set());

  // UI states
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isExporting, setIsExporting] = useState<boolean>(false);
  const [cycleDropdownOpen, setCycleDropdownOpen] = useState<boolean>(false);
  const [deptDropdownOpen, setDeptDropdownOpen] = useState<boolean>(false);
  const [categoryDropdownOpen, setCategoryDropdownOpen] = useState<boolean>(false);

  useEffect(() => {
    loadFilters();
  }, []);

  useEffect(() => {
    if (selectedCycle && selectedDept) {
      loadRatings();
    } else {
      setRatings([]);
    }
  }, [selectedCycle, selectedDept, selectedCategory]);

  const loadFilters = async () => {
    try {
      // Load cycles
      const cyclesResponse = await cycleService.getAllCycles();
      const allCycles = cyclesResponse.data?.cycles || [];
      setCycles(allCycles);

      // Set default to active cycle
      const activeCycle = allCycles.find((c: Cycle) => c.isActive);
      if (activeCycle) {
        setSelectedCycle(activeCycle);
      } else if (allCycles.length > 0) {
        setSelectedCycle(allCycles[0]);
      }

      // Load departments
      const deptsResponse = await departmentService.getDepartments(1, 1000);
      setDepartments(deptsResponse.Data || []);

      // Load categories
      const catsResponse = await categoryService.getCategories(1, 1000);
      setCategories(catsResponse.Data || []);

    } catch (error) {
      console.error('Error loading filters:', error);
    }
  };

  const loadRatings = async () => {
    if (!selectedCycle) {
      return;
    }

    setIsLoading(true);
    try {
      const departmentId = selectedDept?.id ?? '0';
      const cycleId = selectedCycle?._id?.toString() ?? '0';
      const categoryId = selectedCategory?.id ?? '0';

      const filters: any = {};
      if (cycleId !== '0') filters.cycleId = cycleId;
      if (categoryId !== '0') filters.categoryId = categoryId;

      const response = await ratingService.getRatingsByDepartment(departmentId, filters);

      const filtered = (response || []).filter((r: any) => !HIDDEN_USERNAMES.has(r.userName) && !HIDDEN_EMAILS.has(r.userEmail));
      if (filtered.length > 0) {
        setRatings(filtered);
      } else {
        setRatings([]);
      }
    } catch (error: any) {
      console.error('Error loading ratings:', error);
      setRatings([]);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleRowExpansion = (index: number) => {
    const newExpanded = new Set(expandedRows);
    if (newExpanded.has(index)) {
      newExpanded.delete(index);
    } else {
      newExpanded.add(index);
    }
    setExpandedRows(newExpanded);
  };

  const exportToExcel = async () => {
    if (!ratings.length) {
      return;
    }

    if (!selectedCycle) {
      return;
    }

    setIsExporting(true);
    try {
      const ExcelJS = await import('exceljs');
      const { saveAs } = await import('file-saver');

      const workbook = new ExcelJS.Workbook();
      const worksheet = workbook.addWorksheet('Ratings Report');

      // Get all unique years from ratings (sorted)
      const allYears = new Set<number>();
      ratings.forEach(rating => {
        rating.yearlyValues.forEach(yv => allYears.add(yv.year));
      });
      const sortedYears = Array.from(allYears).sort((a, b) => a - b);

      // Determine which year is target year
      const targetYear = selectedCycle?.targetYear;

      // Build dynamic columns
      const baseColumns = ['Category', 'Parameter', 'Department', 'Submitted By'];
      const yearColumns = sortedYears.map(year =>
        year === targetYear ? `${year} (Target)` : `${year} (Actual)`
      );
      const metaColumns = ['Submitted Date', 'Last Updated'];
      const allColumns = [...baseColumns, ...yearColumns, ...metaColumns];

      // Add header row
      const headerRow = worksheet.addRow(allColumns);
      headerRow.eachCell(cell => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = {
          type: 'pattern',
          pattern: 'solid',
          fgColor: { argb: 'FF2563EB' } // Blue header
        };
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
      });

      // Freeze header row
      worksheet.views = [{ state: 'frozen', ySplit: 1 }];

      // Add data rows
      ratings.forEach(rating => {
        const row: any[] = [
          rating.categoryName,
          rating.parameterName,
          rating.departmentName,
          `${rating.userName} (${rating.userEmail})`
        ];

        // Add year values in order
        sortedYears.forEach(year => {
          const yearValue = rating.yearlyValues.find(yv => yv.year === year);
          if (yearValue) {
            const value = year === targetYear
              ? (yearValue.projectedValue || yearValue.actualValue || '-')
              : (yearValue.actualValue || yearValue.projectedValue || '-');
            row.push(value);
          } else {
            row.push('-');
          }
        });

        // Add metadata
        row.push(
          new Date(rating.createdAt).toLocaleDateString(),
          new Date(rating.updatedAt).toLocaleDateString()
        );

        worksheet.addRow(row);
      });

      // Auto-size columns
      worksheet.columns.forEach((col, i) => {
        let maxLength = allColumns[i].length;
        col.eachCell?.({ includeEmpty: true }, cell => {
          const cellValue = cell.value ? cell.value.toString() : '';
          if (cellValue.length > maxLength) maxLength = cellValue.length;
        });
        col.width = Math.min(maxLength + 3, 50); // Max width 50
      });

      // Write file
      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
      });

      const fileName = `ratings_report_${(selectedCycle?.cycleName || 'cycle').replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.xlsx`;
      saveAs(blob, fileName);

    } catch (error: any) {
      console.error('Export error:', error);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="ratings-report-container">
      {/* Page Header */}
      <div className="page-header">
        <h2 className="page-title">Ratings Report</h2>
        <p className="page-subtitle">
          View all parameter submissions across departments and cycles
        </p>
      </div>

      {/* Filters Section */}
      <div className="filters-section">
        <div className="filters-grid">
          {/* Cycle Filter */}
          <div className="filter-group">
            <label className="filter-label">
              <Filter className="label-icon" size={16} />
              Cycle
            </label>
            <div className="custom-dropdown">
              <div
                className="dropdown-trigger"
                onClick={() => setCycleDropdownOpen(!cycleDropdownOpen)}
              >
                <span className="dropdown-value">
                  {selectedCycle?.cycleName || 'Select Cycle'}
                </span>
                <ChevronDown className={`dropdown-icon ${cycleDropdownOpen ? 'rotated' : ''}`} size={20} />
              </div>

              {cycleDropdownOpen && (
                <div className="dropdown-panel">
                  <ul className="dropdown-list">
                    {cycles.map((cycle) => (
                      <li
                        key={cycle._id}
                        className={`dropdown-item ${selectedCycle?._id === cycle._id ? 'selected' : ''}`}
                        onClick={() => {
                          setSelectedCycle(cycle);
                          setCycleDropdownOpen(false);
                        }}
                      >
                        <span className="item-label">{cycle.cycleName || cycle.name}</span>
                        {cycle.isActive && <span className="active-badge">Active</span>}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>

          {/* Department Filter */}
          <div className="filter-group">
            <label className="filter-label">
              <Filter className="label-icon" size={16} />
              Department
            </label>
            <div className="custom-dropdown">
              <div
                className="dropdown-trigger"
                onClick={() => setDeptDropdownOpen(!deptDropdownOpen)}
              >
                <span className="dropdown-value">
                  {selectedDept ? selectedDept.deptName || selectedDept.name : 'Select a Department'}
                </span>
                <ChevronDown className={`dropdown-icon ${deptDropdownOpen ? 'rotated' : ''}`} size={20} />
              </div>

              {deptDropdownOpen && (
                <div className="dropdown-panel">
                  <ul className="dropdown-list">
                    <li
                      className={`dropdown-item ${!selectedDept ? 'selected' : ''}`}
                      onClick={() => {
                        setSelectedDept(null);
                        setDeptDropdownOpen(false);
                      }}
                    >
                      Select a Department
                    </li>
                    {departments.map((dept) => (
                      <li
                        key={dept.id}
                        className={`dropdown-item ${selectedDept?.id === dept.id ? 'selected' : ''}`}
                        onClick={() => {
                          setSelectedDept(dept);
                          setDeptDropdownOpen(false);
                        }}
                      >
                        {dept.deptName || dept.name}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>

          {/* Category Filter */}
          <div className="filter-group">
            <label className="filter-label">
              <Filter className="label-icon" size={16} />
              Category (Strategic Pillar)
            </label>
            <div className="custom-dropdown">
              <div
                className="dropdown-trigger"
                onClick={() => setCategoryDropdownOpen(!categoryDropdownOpen)}
              >
                <span className="dropdown-value">
                  {selectedCategory ? selectedCategory.name : 'All Categories'}
                </span>
                <ChevronDown className={`dropdown-icon ${categoryDropdownOpen ? 'rotated' : ''}`} size={20} />
              </div>

              {categoryDropdownOpen && (
                <div className="dropdown-panel">
                  <ul className="dropdown-list">
                    <li
                      className={`dropdown-item ${!selectedCategory ? 'selected' : ''}`}
                      onClick={() => {
                        setSelectedCategory(null);
                        setCategoryDropdownOpen(false);
                      }}
                    >
                      All Categories
                    </li>
                    {categories.map((cat) => (
                      <li
                        key={cat.id}
                        className={`dropdown-item ${selectedCategory?.id === cat.id ? 'selected' : ''}`}
                        onClick={() => {
                          setSelectedCategory(cat);
                          setCategoryDropdownOpen(false);
                        }}
                      >
                        {cat.name}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Actions Bar */}
        <div className="actions-bar">
          <div className="results-count">
            {ratings.length > 0 && (
              <span className="count-text">
                Showing <strong>{ratings.length}</strong> submission{ratings.length !== 1 ? 's' : ''}
              </span>
            )}
          </div>
          <button
            className="export-button"
            onClick={exportToExcel}
            disabled={isExporting || ratings.length === 0}
          >
            <FileSpreadsheet size={18} />
            {isExporting ? 'Exporting...' : 'Export to Excel'}
          </button>
        </div>
      </div>

      {/* Ratings Table */}
      {!isLoading && ratings.length > 0 && (
        <div className="ratings-table-container">
          <table className="ratings-table">
            <thead>
              <tr>
                <th className="col-expand"></th>
                <th className="col-category">Category</th>
                <th className="col-parameter">Parameter</th>
                <th className="col-department">Department</th>
                <th className="col-user">Submitted By</th>
                <th className="col-submissions">Submissions</th>
              </tr>
            </thead>
            <tbody>
              {ratings.map((rating, index) => (
                <React.Fragment key={index}>
                  <tr
                    className={`table-row ${expandedRows.has(index) ? 'expanded' : ''}`}
                    onClick={() => toggleRowExpansion(index)}
                  >
                    <td className="col-expand">
                      {expandedRows.has(index) ? (
                        <ChevronDown className="expand-icon" size={20} />
                      ) : (
                        <ChevronRight className="expand-icon" size={20} />
                      )}
                    </td>
                    <td className="col-category">
                      <span className="category-badge">{rating.categoryName}</span>
                    </td>
                    <td className="col-parameter">
                      <span className="parameter-name">{rating.parameterName}</span>
                    </td>
                    <td className="col-department">{rating.departmentName}</td>
                    <td className="col-user">
                      <div className="user-info">
                        <span className="user-name">{rating.userName}</span>
                        <span className="user-email">{rating.userEmail}</span>
                      </div>
                    </td>
                    <td className="col-submissions">
                      <span className="submission-count">
                        {rating.yearlyValues.length} year{rating.yearlyValues.length !== 1 ? 's' : ''}
                      </span>
                    </td>
                  </tr>
                  {expandedRows.has(index) && (
                    <tr className="expanded-row">
                      <td colSpan={6}>
                        <div className="expanded-content">
                          <h4 className="expanded-title">Year-wise Submissions</h4>
                          <div className="years-grid">
                            {rating.yearlyValues
                              .sort((a, b) => a.year - b.year)
                              .flatMap((yv, yIndex) => {
                                const isTargetYear = selectedCycle?.targetYear === yv.year;
                                const cards = [];

                                // Show actual value card if it exists
                                if (yv.actualValue !== null && yv.actualValue !== undefined) {
                                  cards.push(
                                    <div key={`${yIndex}-actual`} className="year-card">
                                      <div className="year-header">
                                        <span className="year-label">{yv.year}</span>
                                        <span className="year-type actual">Actual</span>
                                      </div>
                                      <div className="year-value">{yv.actualValue}</div>
                                      {yv.textValue && (
                                        <div className="year-text">{yv.textValue}</div>
                                      )}
                                    </div>
                                  );
                                }

                                // Show projected/target value card if it exists
                                if (yv.projectedValue !== null && yv.projectedValue !== undefined) {
                                  cards.push(
                                    <div key={`${yIndex}-projected`} className="year-card">
                                      <div className="year-header">
                                        <span className="year-label">{yv.year}</span>
                                        <span className="year-type target">
                                          {isTargetYear ? 'Target' : 'Projected'}
                                        </span>
                                      </div>
                                      <div className="year-value">{yv.projectedValue}</div>
                                      {yv.textValue && (
                                        <div className="year-text">{yv.textValue}</div>
                                      )}
                                    </div>
                                  );
                                }

                                // If neither exists, show empty card
                                if (cards.length === 0) {
                                  cards.push(
                                    <div key={`${yIndex}-empty`} className="year-card">
                                      <div className="year-header">
                                        <span className="year-label">{yv.year}</span>
                                        <span className="year-type actual">No Data</span>
                                      </div>
                                      <div className="year-value">-</div>
                                    </div>
                                  );
                                }

                                return cards;
                              })}
                          </div>
                          <div className="expanded-meta">
                            <span className="meta-item">
                              <strong>Submitted:</strong> {new Date(rating.createdAt).toLocaleString()}
                            </span>
                            <span className="meta-item">
                              <strong>Last Updated:</strong> {new Date(rating.updatedAt).toLocaleString()}
                            </span>
                          </div>
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && ratings.length === 0 && (
        <div className="empty-state">
          <div className="empty-icon">📊</div>
          {!selectedDept ? (
            <>
              <h3 className="empty-title">Select a Department</h3>
              <p className="empty-text">Choose a department from the filter above to view its submissions.</p>
            </>
          ) : (
            <>
              <h3 className="empty-title">No submissions found</h3>
              <p className="empty-text">Try adjusting your filters to see more results.</p>
            </>
          )}
        </div>
      )}

      {/* Loading State */}
      {isLoading && (
        <div className="loading-state">
          <div className="loading-spinner"></div>
          <p className="loading-text">Loading ratings data...</p>
        </div>
      )}
    </div>
  );
};

export default RatingsReportNew;
