import axios from 'axios';
import { User, UserFormData, ApiResponse, PaginatedResponse } from '../types';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/';

class UserService {
  private axiosInstance;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });

    // Request interceptor to add auth token
    this.axiosInstance.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token');
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => {
        return Promise.reject(error);
      }
    );

    // Response interceptor for error handling
    this.axiosInstance.interceptors.response.use(
      (response) => response,
      (error) => {
        if (error.response?.status === 401) {
          // Token expired or invalid
          localStorage.removeItem('token');
          localStorage.removeItem('userRole');
          localStorage.removeItem('tokenExpiration');
          window.location.href = '/';
        }
        return Promise.reject(error);
      }
    );
  }

  async getUsers(page: number = 1, pageSize: number = 10, search: string = ''): Promise<PaginatedResponse<User>> {
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        pageSize: pageSize.toString(),
        ...(search && { search })
      });

      const response = await this.axiosInstance.get(`/api/users/get-all-users?${params.toString()}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to fetch users');
    }
  }

  async getUserById(id: string): Promise<ApiResponse<User>> {
    try {
      const response = await this.axiosInstance.get(`/api/users/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch user');
    }
  }

  async createUser(userData: UserFormData): Promise<ApiResponse<User>> {
    try {
      // Transform camelCase to PascalCase for MERN backend
      const backendData = {
        Username: userData.userName,
        Email: userData.email,
        Password: userData.password,
        UserRole: userData.userRole,
        PhoneNumber: userData.phoneNumber || '',
        FacultyId: userData.facultyId || '',
        DeptId: userData.deptId || '',
        FirstName: userData.firstName,
        LastName: userData.lastName
      };
      
      const response = await this.axiosInstance.post('/api/auth/register', backendData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to create user');
    }
  }

  async updateUser(id: string, userData: UserFormData): Promise<ApiResponse<User>> {
    try {
      // Transform camelCase to PascalCase for MERN backend
      const backendData = {
        Username: userData.userName,
        Email: userData.email,
        Password: userData.password || '', // Optional for updates
        UserRole: userData.userRole,
        PhoneNumber: userData.phoneNumber || '',
        FacultyId: userData.facultyId || '',
        DeptId: userData.deptId || '',
        FirstName: userData.firstName,
        LastName: userData.lastName
      };
      
      const response = await this.axiosInstance.post(`/api/auth/update-user/${userData.userName || id}`, backendData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to update user');
    }
  }

  async deleteUser(id: string): Promise<ApiResponse<any>> {
    try {
      const response = await this.axiosInstance.delete(`/api/users/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to delete user');
    }
  }

  // Get current user profile
  async getCurrentUser(): Promise<ApiResponse<User>> {
    try {
      const response = await this.axiosInstance.get('/api/users/get-current-user');
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to get current user profile');
    }
  }

  // Get users by role
  async getUsersByRole(role: string): Promise<ApiResponse<User[]>> {
    try {
      const response = await this.axiosInstance.get(`/User/role/${role}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch users by role');
    }
  }

  // Get users by department
  async getUsersByDepartment(departmentId: string): Promise<ApiResponse<User[]>> {
    try {
      const response = await this.axiosInstance.get(`/User/department/${departmentId}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch users by department');
    }
  }

  // Get users by faculty
  async getUsersByFaculty(facultyId: string): Promise<ApiResponse<User[]>> {
    try {
      const response = await this.axiosInstance.get(`/User/faculty/${facultyId}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch users by faculty');
    }
  }

  // Update user role (admin only)
  async updateUserRole(id: string, newRole: string): Promise<ApiResponse<User>> {
    try {
      const response = await this.axiosInstance.put(`/User/${id}/role`, { userRole: newRole });
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to update user role');
    }
  }

  // Reset user password (admin only)
  async resetUserPassword(id: string, newPassword: string): Promise<ApiResponse<any>> {
    try {
      const response = await this.axiosInstance.put(`/User/${id}/reset-password`, { 
        newPassword 
      });
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to reset user password');
    }
  }
}

export const userService = new UserService();