import React from 'react';
import ParameterListView from '../parameter-list-view/ParameterListView';
import './GenericForms.css';

interface GenericFormsProps {
  categoryName: string;
  onClose: () => void;
  onSuccess?: () => void;
}

const GenericForms: React.FC<GenericFormsProps> = ({
  categoryName,
  onClose,
  onSuccess
}) => {
  const handleSuccess = () => {
    if (onSuccess) {
      onSuccess();
    }
  };

  return (
    <div className="generic-forms">
      <ParameterListView
        categoryName={categoryName}
        onClose={onClose}
        onSuccess={handleSuccess}
      />
    </div>
  );
};

export default GenericForms;