import axios from 'axios';
import { Department, DepartmentFormData, ApiResponse, PaginatedResponse } from '../types';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/';

class DepartmentService {
  private axiosInstance;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });

    // Request interceptor to add auth token
    this.axiosInstance.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token');
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => {
        return Promise.reject(error);
      }
    );

    // Response interceptor for error handling
    this.axiosInstance.interceptors.response.use(
      (response) => response,
      (error) => {
        if (error.response?.status === 401) {
          // Token expired or invalid
          localStorage.removeItem('token');
          localStorage.removeItem('userRole');
          localStorage.removeItem('tokenExpiration');
          window.location.href = '/';
        }
        return Promise.reject(error);
      }
    );
  }

  async getDepartments(page: number = 1, pageSize: number = 10, search: string = ''): Promise<PaginatedResponse<Department>> {
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        pageSize: pageSize.toString(),
        ...(search && { search })
      });

      const response = await this.axiosInstance.get(`/api/departments?${params.toString()}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to fetch departments');
    }
  }

  async getDepartmentById(id: string): Promise<ApiResponse<Department>> {
    try {
      const response = await this.axiosInstance.get(`/api/departments/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch department');
    }
  }

  async createDepartment(departmentData: DepartmentFormData): Promise<ApiResponse<Department>> {
    try {
      const response = await this.axiosInstance.post('/api/departments', departmentData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to create department');
    }
  }

  async updateDepartment(id: string, departmentData: DepartmentFormData): Promise<ApiResponse<Department>> {
    try {
      const response = await this.axiosInstance.put(`/api/departments/${id}`, departmentData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to update department');
    }
  }

  async deleteDepartment(id: string): Promise<ApiResponse<any>> {
    try {
      const response = await this.axiosInstance.delete(`/api/departments/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to delete department');
    }
  }

  // Get departments by faculty (for filtering/dropdown)
  async getDepartmentsByFaculty(facultyId: string): Promise<ApiResponse<Department[]>> {
    try {
      const response = await this.axiosInstance.get(`/api/departments?facultyId=${facultyId}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch departments by faculty');
    }
  }
}

export const departmentService = new DepartmentService();