import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { categoryService } from '../../services/categoryService';
import { Category, CategoryFormData } from '../../types';
import { toast } from 'react-hot-toast';
import './CategoryModal.css';

interface CategoryModalProps {
  category: Category | null;
  isVisible: boolean;
  onClose: () => void;
  onSave: () => void;
}

const CategoryModal: React.FC<CategoryModalProps> = ({
  category,
  isVisible,
  onClose,
  onSave
}) => {
  const [formData, setFormData] = useState<CategoryFormData>({
    name: "",
    description: "",
    sortOrder: 1,
  });
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  useEffect(() => {
    if (isVisible) {
      if (category) {
        // Edit mode - populate form with existing data
        setFormData({
          name: category.name,
          description: category.description || "",
          sortOrder: category.sortOrder,
        });
      } else {
        // Add mode - reset form
        setFormData({
          name: "",
          description: "",
          sortOrder: 1,
        });
      }
      setErrors({});
    }
  }, [category, isVisible]);

  const validateForm = (): boolean => {
    const newErrors: { [key: string]: string } = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Pillar name is required';
    }

    if (formData.sortOrder < 1) {
      newErrors.sortOrder = "Sort order must be at least 1";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: keyof CategoryFormData) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    const value = field === 'sortOrder' ? parseInt(e.target.value) || 1 : e.target.value;
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));

    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();


    if (!validateForm()) {
      return;
    }

    setIsLoading(true);


    try {
      if (category) {
        // Edit existing category
        await categoryService.updateCategory(category.id, formData);
        toast.success('Pillar updated successfully!');
      } else {
        // Create new category
        await categoryService.createCategory(formData);
        toast.success('Pillar created successfully!');
      }


      onSave(); // Refresh parent data and close modal
    } catch (error: any) {
      toast.error(error.message || "Operation failed");
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading) {
      onClose();
    }
  };

  if (!isVisible) return null;

  return createPortal(
    <div className="modal-backdrop" onClick={handleClose}>
      <div className="p-dialog p-component" onClick={(e) => e.stopPropagation()}>
        <div className="p-dialog-content">
          <div className="p-dialog-wrapper">
            {/* Modal Header */}
            <div className="p-dialog-header">
              <span className="p-dialog-title">
                {category ? 'Edit Pillar' : 'Add Pillar'}
              </span>
              <div className="p-dialog-header-icons">
                <button
                  className="p-dialog-header-icon p-dialog-header-close"
                  type="button"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  <X className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Modal Body */}
            <form onSubmit={handleSubmit} className="category-form">
              <div className="p-fluid">
                {/* Category Name Field */}
                <div className="field col-12">
                  <label htmlFor="categoryName" className="required-field">
                    Pillar Name
                  </label>
                  <input
                    id="categoryName"
                    type="text"
                    placeholder="Enter pillar name"
                    value={formData.name}
                    onChange={handleInputChange('name')}
                    className={`p-inputtext p-component ${errors.name ? 'p-invalid' : ''}`}
                    disabled={isLoading}
                    required
                  />
                  {errors.name && (
                    <small className="p-error">{errors.name}</small>
                  )}
                </div>

                {/* Category Description Field */}
                <div className="field col-12">
                  <label htmlFor="categoryDescription">
                    Pillar Description
                  </label>
                  <textarea
                    id="categoryDescription"
                    placeholder="Enter pillar description (optional)"
                    value={formData.description}
                    onChange={handleInputChange('description')}
                    className="p-inputtextarea p-inputtext p-component"
                    rows={3}
                    disabled={isLoading}
                  />
                </div>

                {/* Sort Order Field */}
                <div className="field col-12">
                  <label htmlFor="sortOrder" className="required-field">
                    Sort Order
                  </label>
                  <input
                    id="sortOrder"
                    type="number"
                    placeholder="1"
                    value={formData.sortOrder}
                    onChange={handleInputChange('sortOrder')}
                    className={`p-inputtext p-component ${errors.sortOrder ? 'p-invalid' : ''}`}
                    min="1"
                    disabled={isLoading}
                    required
                  />
                  {errors.sortOrder && (
                    <small className="p-error">{errors.sortOrder}</small>
                  )}
                </div>
              </div>

              {/* Modal Footer */}
              <div className="p-dialog-footer">
                <button
                  type="button"
                  className="p-button p-component p-button-secondary"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="p-button p-component p-button-primary"
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <span className="p-button-loading-icon pi pi-spinner pi-spin"></span>
                  ) : null}
                  {isLoading
                    ? 'Saving...'
                    : (category ? 'Update Pillar' : 'Create Pillar')
                  }
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

export default CategoryModal;

