import axios from 'axios';
import { Category, PaginatedResponse, ApiResponse, CategoryFormData } from '../types';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/';

class CategoryService {
  private axiosInstance;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });

    // Request interceptor to add auth token
    this.axiosInstance.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token');
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => {
        return Promise.reject(error);
      }
    );

    // Response interceptor for error handling
    this.axiosInstance.interceptors.response.use(
      (response) => response,
      (error) => {
        if (error.response?.status === 401) {
          // Token expired or invalid
          localStorage.removeItem('token');
          localStorage.removeItem('userRole');
          localStorage.removeItem('tokenExpiration');
          window.location.href = '/';
        }
        return Promise.reject(error);
      }
    );
  }

  async getCategories(page: number = 1, pageSize: number = 10, search?: string): Promise<PaginatedResponse<Category>> {
    try {
      const params = new URLSearchParams();
      params.append('page', page.toString());
      params.append('pageSize', pageSize.toString());
      if (search) {
        params.append('search', search);
      }

      const response = await this.axiosInstance.get(`/api/category?${params.toString()}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch categories');
    }
  }

  async getCategoryById(id: string): Promise<ApiResponse<Category>> {
    try {
      const response = await this.axiosInstance.get(`/api/category/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch category');
    }
  }

  async createCategory(category: CategoryFormData): Promise<ApiResponse<Category>> {
    try {
      const response = await this.axiosInstance.post('/api/category', category);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to create category');
    }
  }

  async updateCategory(id: string, category: Partial<CategoryFormData>): Promise<ApiResponse<Category>> {
    try {
      const response = await this.axiosInstance.put(`/api/category/${id}`, category);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to update category');
    }
  }

  async deleteCategory(id: string): Promise<ApiResponse<null>> {
    try {
      const response = await this.axiosInstance.delete(`/api/category/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to delete category');
    }
  }

  async getCategoriesWithProgress(): Promise<ApiResponse<Category[]>> {
    try {
      // Add timestamp to prevent caching - for dashboard
      const timestamp = Date.now();
      const response = await this.axiosInstance.get(`/api/category?t=${timestamp}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch categories with progress');
    }
  }
}

export const categoryService = new CategoryService();