import React, { useState } from 'react';
import {
  pillarStatus, faculties, universitySummary, lowestSubmissions,
  heatmapData, yearProgress, cycleYears, activeYear,
  pillarPerformance, universityPerformance, universityOnTrackPct,
} from './mockData';

const completionColor = (pct: number) => {
  if (pct >= 85) return '#10b981';
  if (pct >= 60) return '#f59e0b';
  return '#ef4444';
};

const heatColor = (val: number) => {
  if (val === 0) return '#f3f4f6';
  if (val >= 85) return '#bbf7d0';
  if (val >= 70) return '#d9f99d';
  if (val >= 55) return '#fef08a';
  if (val >= 40) return '#fed7aa';
  return '#fecaca';
};
const heatTextColor = (val: number) => {
  if (val === 0) return '#9ca3af';
  if (val >= 70) return '#166534';
  if (val >= 55) return '#92400e';
  return '#991b1b';
};


const UniversityOverview: React.FC = () => {
  const [heatmapYear, setHeatmapYear] = useState<number | 'overall'>('overall');
  const pillarData = [...pillarStatus].sort((a, b) => a.completionRate - b.completionRate);
  const facultyCodes = faculties.map(f => f.code);
  const pillarShorts = pillarStatus.map(p => p.shortName);

  const filteredHeatmap = heatmapYear === 'overall'
    ? (() => {
        const grouped: Record<string, number[]> = {};
        heatmapData.forEach(h => {
          const key = `${h.pillarShort}__${h.facultyCode}`;
          if (!grouped[key]) grouped[key] = [];
          if (h.value > 0) grouped[key].push(h.value);
        });
        return Object.entries(grouped).map(([key, vals]) => {
          const [pillarShort, facultyCode] = key.split('__');
          return { pillarShort, facultyCode, value: vals.length > 0 ? Math.round(vals.reduce((a, b) => a + b, 0) / vals.length) : 0 };
        });
      })()
    : heatmapData
        .filter(h => h.year === heatmapYear)
        .map(h => ({ pillarShort: h.pillarShort, facultyCode: h.facultyCode, value: h.value }));

  return (
    <div className="space-y-6">
      {/* ── Headline: Data Collection Progress ── */}
      <div className="bg-white rounded-xl border border-gray-200 p-6">
        <div className="flex items-center justify-between mb-2">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">Strategic Plan — Data Collection Progress</h3>
            <p className="text-sm text-gray-500">Cycle {universitySummary.activeCycle} · Tracking submissions across all departments</p>
          </div>
          <div className="flex items-center gap-6">
            <div className="text-center">
              <div className="text-xs text-gray-500 mb-0.5">Overall Cycle</div>
              <div className="text-2xl font-bold" style={{ color: completionColor(universitySummary.overallCyclePct) }}>
                {universitySummary.overallCyclePct}%
              </div>
            </div>
            <div className="text-center">
              <div className="text-xs text-gray-500 mb-0.5">Active Year ({activeYear})</div>
              <div className="text-2xl font-bold" style={{ color: completionColor(universitySummary.activeYearPct) }}>
                {universitySummary.activeYearPct}%
              </div>
            </div>
          </div>
        </div>

        <div className="space-y-2.5 mt-4">
          {yearProgress.map(yp => (
            <div key={yp.year} className="flex items-center gap-3">
              <div className={`w-28 text-sm shrink-0 ${yp.isActive ? 'font-bold text-blue-700' : 'text-gray-600'}`}>
                {yp.label}
              </div>
              <div className="flex-1 bg-gray-100 rounded-full h-4 relative">
                <div
                  className="h-4 rounded-full transition-all"
                  style={{
                    width: `${yp.pct}%`,
                    backgroundColor: yp.pct === 0 ? '#e5e7eb' : yp.isActive ? '#3b82f6' : completionColor(yp.pct),
                    minWidth: yp.pct > 0 ? 8 : 0,
                  }}
                />
              </div>
              <div className="w-20 text-right shrink-0">
                <span className={`text-sm font-semibold ${yp.isActive ? 'text-blue-700' : ''}`} style={yp.isActive ? {} : { color: yp.pct === 0 ? '#9ca3af' : completionColor(yp.pct) }}>
                  {yp.pct > 0 ? `${yp.pct}%` : '—'}
                </span>
              </div>
              <div className="w-32 text-xs text-gray-400 shrink-0 text-right">
                {yp.submitted > 0 ? `${yp.submitted.toLocaleString()} / ${yp.expected.toLocaleString()}` : 'Not started'}
              </div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-3 gap-3 mt-5 pt-4 border-t border-gray-100">
          <div className="bg-gray-50 rounded-lg p-3 text-center">
            <div className="text-xl font-bold text-gray-900">{universitySummary.totalDepartments}</div>
            <div className="text-xs text-gray-500">Departments</div>
          </div>
          <div className="bg-gray-50 rounded-lg p-3 text-center">
            <div className="text-xl font-bold text-gray-900">{universitySummary.totalParameters}</div>
            <div className="text-xs text-gray-500">Parameters</div>
          </div>
          <div className="bg-gray-50 rounded-lg p-3 text-center">
            <div className="text-xl font-bold text-emerald-600">{universitySummary.deptComplete}</div>
            <div className="text-xs text-gray-500">Fully Reported</div>
          </div>
        </div>
      </div>

      {/* ── Heatmap with year filter ── */}
      <div className="bg-white rounded-xl border border-gray-200 p-6">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">Strategic Coverage Map</h3>
            <p className="text-sm text-gray-500">Data collection rates across pillars and faculties</p>
          </div>
          <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-0.5">
            <button
              onClick={() => setHeatmapYear('overall')}
              className={`px-3 py-1.5 rounded-md text-xs font-medium transition-all ${
                heatmapYear === 'overall' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              Overall
            </button>
            {cycleYears.map(y => (
              <button
                key={y}
                onClick={() => setHeatmapYear(y)}
                className={`px-3 py-1.5 rounded-md text-xs font-medium transition-all ${
                  heatmapYear === y ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                } ${y === activeYear && heatmapYear !== y ? 'text-blue-600' : ''}`}
              >
                {y}
              </button>
            ))}
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr>
                <th className="text-left py-2 pr-2 font-medium text-gray-600 min-w-[150px]">Pillar</th>
                {facultyCodes.map(code => (
                  <th key={code} className="text-center py-2 px-2 font-medium text-gray-600 min-w-[80px]">{code}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {pillarShorts.map(pillar => (
                <tr key={pillar}>
                  <td className="py-1.5 pr-2 font-medium text-gray-700 text-xs">{pillar}</td>
                  {facultyCodes.map(fc => {
                    const cell = filteredHeatmap.find(h => h.pillarShort === pillar && h.facultyCode === fc);
                    const val = cell?.value ?? 0;
                    return (
                      <td key={fc} className="py-1.5 px-1 text-center">
                        <div
                          className="rounded px-2 py-2 font-semibold text-xs"
                          style={{ backgroundColor: heatColor(val), color: heatTextColor(val) }}
                        >
                          {val > 0 ? `${val}%` : '—'}
                        </div>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="flex items-center gap-4 mt-3 text-xs text-gray-500">
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#bbf7d0' }} /> 85%+</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#d9f99d' }} /> 70-84%</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#fef08a' }} /> 55-69%</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#fed7aa' }} /> 40-54%</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#fecaca' }} /> &lt;40%</span>
          <span className="flex items-center gap-1"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#f3f4f6' }} /> No data</span>
        </div>
      </div>

      {/* ── Performance Against Targets ── */}
      <div className="bg-white rounded-xl border border-gray-200 p-6">
        <div className="flex items-center justify-between mb-5">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">Performance Against Targets</h3>
            <p className="text-sm text-gray-500 mt-0.5">
              For each parameter: is the achieved value meeting the projected target for {activeYear}?
            </p>
          </div>
          <div className="text-right">
            <div className="text-2xl font-bold" style={{ color: completionColor(universityOnTrackPct) }}>{universityOnTrackPct}%</div>
            <div className="text-xs text-gray-500">Parameters on track</div>
          </div>
        </div>

        {/* Summary cards */}
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 mb-6">
          <div className="rounded-lg p-3 text-center" style={{ backgroundColor: '#ecfdf5' }}>
            <div className="text-xl font-bold text-emerald-700">{universityPerformance.exceeding}</div>
            <div className="text-xs text-emerald-600 mt-0.5">Exceeding Target</div>
          </div>
          <div className="rounded-lg p-3 text-center" style={{ backgroundColor: '#eff6ff' }}>
            <div className="text-xl font-bold text-blue-700">{universityPerformance.meeting}</div>
            <div className="text-xs text-blue-600 mt-0.5">Meeting Target</div>
          </div>
          <div className="rounded-lg p-3 text-center" style={{ backgroundColor: '#fef2f2' }}>
            <div className="text-xl font-bold text-red-700">{universityPerformance.below}</div>
            <div className="text-xs text-red-600 mt-0.5">Below Target</div>
          </div>
          <div className="rounded-lg p-3 text-center" style={{ backgroundColor: '#fffbeb' }}>
            <div className="text-xl font-bold text-amber-700">{universityPerformance.noActualYet}</div>
            <div className="text-xs text-amber-600 mt-0.5">Awaiting Achieved</div>
          </div>
          <div className="rounded-lg p-3 text-center bg-gray-50">
            <div className="text-xl font-bold text-gray-500">{universityPerformance.noTargetYet}</div>
            <div className="text-xs text-gray-400 mt-0.5">Targets Not Set</div>
          </div>
        </div>

        {/* Per-pillar breakdown: stacked horizontal bars */}
        <h4 className="text-sm font-semibold text-gray-700 mb-3">Breakdown by Strategic Pillar</h4>
        <div className="space-y-2.5">
          {pillarPerformance.map(p => {
            const tracked = p.breakdown.exceeding + p.breakdown.meeting + p.breakdown.below;
            const total = tracked + p.breakdown.noActualYet + p.breakdown.noTargetYet;
            if (total === 0) return null;
            return (
              <div key={p.pillarId}>
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs font-medium text-gray-700">{p.shortName}</span>
                  <span className="text-xs font-semibold" style={{ color: completionColor(p.onTrackPct) }}>{p.onTrackPct}% on track</span>
                </div>
                <div className="flex h-3 rounded-full overflow-hidden bg-gray-100">
                  {p.breakdown.exceeding > 0 && (
                    <div style={{ width: `${(p.breakdown.exceeding / total) * 100}%`, backgroundColor: '#10b981' }} title={`${p.breakdown.exceeding} exceeding`} />
                  )}
                  {p.breakdown.meeting > 0 && (
                    <div style={{ width: `${(p.breakdown.meeting / total) * 100}%`, backgroundColor: '#3b82f6' }} title={`${p.breakdown.meeting} meeting`} />
                  )}
                  {p.breakdown.below > 0 && (
                    <div style={{ width: `${(p.breakdown.below / total) * 100}%`, backgroundColor: '#ef4444' }} title={`${p.breakdown.below} below`} />
                  )}
                  {p.breakdown.noActualYet > 0 && (
                    <div style={{ width: `${(p.breakdown.noActualYet / total) * 100}%`, backgroundColor: '#fbbf24' }} title={`${p.breakdown.noActualYet} awaiting achieved values`} />
                  )}
                  {p.breakdown.noTargetYet > 0 && (
                    <div style={{ width: `${(p.breakdown.noTargetYet / total) * 100}%`, backgroundColor: '#e5e7eb' }} title={`${p.breakdown.noTargetYet} no targets`} />
                  )}
                </div>
              </div>
            );
          })}
        </div>
        <div className="flex items-center gap-5 mt-4 text-xs text-gray-500">
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#10b981' }} /> Exceeding</span>
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#3b82f6' }} /> Meeting</span>
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#ef4444' }} /> Below</span>
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#fbbf24' }} /> Awaiting Achieved</span>
          <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded" style={{ backgroundColor: '#e5e7eb' }} /> Targets Not Set</span>
        </div>
      </div>

      {/* ── Pillar Bar (HALF) + Faculty Breakdown (HALF) ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white rounded-xl border border-gray-200 p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-1">Data Collection by Pillar</h3>
          <p className="text-sm text-gray-500 mb-4">Weakest pillars first — where data gaps exist</p>
          <div className="space-y-3">
            {pillarData.map(p => (
              <div key={p.id}>
                <div className="flex items-center justify-between mb-1">
                  <span className="text-sm font-medium text-gray-700">{p.shortName}</span>
                  <span className="text-sm font-bold" style={{ color: completionColor(p.completionRate) }}>{p.completionRate}%</span>
                </div>
                <div className="w-full bg-gray-100 rounded-full h-2.5">
                  <div className="h-2.5 rounded-full transition-all" style={{ width: `${p.completionRate}%`, backgroundColor: completionColor(p.completionRate) }} />
                </div>
                <div className="text-xs text-gray-400 mt-0.5">{p.receivedSubmissions} / {p.expectedSubmissions} submissions</div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white rounded-xl border border-gray-200 p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-1">Faculty Breakdown</h3>
          <p className="text-sm text-gray-500 mb-4">Data collection progress per faculty</p>
          <div className="space-y-5">
            {[...faculties].sort((a, b) => b.completionPct - a.completionPct).map(f => (
              <div key={f.id}>
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-sm font-semibold text-gray-800">{f.code} <span className="font-normal text-gray-400">— {f.name}</span></span>
                  <span className="text-sm font-bold" style={{ color: completionColor(f.completionPct) }}>{f.completionPct}%</span>
                </div>
                <div className="w-full bg-gray-100 rounded-full h-3">
                  <div className="h-3 rounded-full transition-all" style={{ width: `${f.completionPct}%`, backgroundColor: completionColor(f.completionPct) }} />
                </div>
                <div className="flex items-center justify-between mt-1 text-xs text-gray-400">
                  <span>{f.totalSubmitted.toLocaleString()} / {f.totalExpected.toLocaleString()} submissions</span>
                  <span>{f.deptComplete}/{f.departments.length} depts complete</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ── Follow-Up Table ── */}
      <div className="bg-white rounded-xl border border-gray-200 p-6">
        <h3 className="text-lg font-semibold text-gray-900 mb-1">Departments Needing Follow-Up</h3>
        <p className="text-sm text-gray-500 mb-4">Lowest data collection rates across the university</p>
        <div className="overflow-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-200">
                <th className="text-left py-2 pr-3 font-medium text-gray-600">Department</th>
                <th className="text-left py-2 pr-3 font-medium text-gray-600">Faculty</th>
                <th className="text-center py-2 pr-3 font-medium text-gray-600">Submitted</th>
                <th className="text-center py-2 pr-3 font-medium text-gray-600">Targets</th>
                <th className="text-center py-2 pr-3 font-medium text-gray-600">Achieved</th>
                <th className="text-left py-2 font-medium text-gray-600">Progress</th>
              </tr>
            </thead>
            <tbody>
              {lowestSubmissions.map(dept => (
                <tr key={dept.id} className="border-b border-gray-50 hover:bg-gray-50">
                  <td className="py-2.5 pr-3 font-medium text-gray-900">{dept.name}</td>
                  <td className="py-2.5 pr-3 text-gray-500">{dept.facultyCode}</td>
                  <td className="py-2.5 pr-3 text-center font-semibold" style={{ color: completionColor(dept.completionPct) }}>
                    {dept.totalSubmitted}/{dept.totalExpected}
                  </td>
                  <td className="py-2.5 pr-3 text-center text-gray-600">{dept.targetValuesLocked}</td>
                  <td className="py-2.5 pr-3 text-center text-gray-600">{dept.actualsSubmitted}</td>
                  <td className="py-2.5">
                    <div className="flex items-center gap-2">
                      <div className="w-24 bg-gray-100 rounded-full h-2">
                        <div className="h-2 rounded-full" style={{ width: `${dept.completionPct}%`, backgroundColor: completionColor(dept.completionPct) }} />
                      </div>
                      <span className="text-xs font-medium" style={{ color: completionColor(dept.completionPct) }}>{dept.completionPct}%</span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default UniversityOverview;
