import React, { useState } from 'react';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '../ui/dialog';
import { Eye, EyeOff } from 'lucide-react';
import { authService } from '../../services/authService';
import { toast } from 'react-hot-toast';
import './UpdatePasswordModal.css';

interface UpdatePasswordModalProps {
  isOpen: boolean;
  onClose: () => void;
}

interface PasswordForm {
  oldPassword: string;
  newPassword: string;
  confirmPassword: string;
}

const UpdatePasswordModal: React.FC<UpdatePasswordModalProps> = ({ 
  isOpen, 
  onClose 
}) => {
  const [formData, setFormData] = useState<PasswordForm>({
    oldPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  
  const [showPasswords, setShowPasswords] = useState({
    old: false,
    new: false,
    confirm: false
  });
  
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (field: keyof PasswordForm) => (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData(prev => ({
      ...prev,
      [field]: e.target.value
    }));
  };

  const togglePasswordVisibility = (field: 'old' | 'new' | 'confirm') => {
    setShowPasswords(prev => ({
      ...prev,
      [field]: !prev[field]
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validation
    if (!formData.oldPassword || !formData.newPassword || !formData.confirmPassword) {
      toast.error('Please fill in all fields');
      return;
    }

    if (formData.newPassword !== formData.confirmPassword) {
      toast.error('New passwords do not match');
      return;
    }

    if (formData.newPassword.length < 6) {
      toast.error('New password must be at least 6 characters');
      return;
    }

    setIsLoading(true);
    
    try {
      const username = localStorage.getItem('username') || '';
      
      await authService.updatePassword({
        Username: username,
        OldPassword: formData.oldPassword,
        NewPassword: formData.newPassword
      });

      toast.success('Password updated successfully');
      onClose();
      
      // Reset form
      setFormData({
        oldPassword: '',
        newPassword: '',
        confirmPassword: ''
      });
      
    } catch (error: any) {
      toast.error(error.message || 'Failed to update password');
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    // Reset form when closing
    setFormData({
      oldPassword: '',
      newPassword: '',
      confirmPassword: ''
    });
    setShowPasswords({
      old: false,
      new: false,
      confirm: false
    });
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="update-password-modal">
        <DialogHeader>
          <DialogTitle>Change Password</DialogTitle>
        </DialogHeader>
        
        <form onSubmit={handleSubmit} className="password-form">
          {/* Old Password */}
          <div className="form-field">
            <label htmlFor="oldPassword" className="block text-900 font-medium mb-2">
              Current Password
            </label>
            <div className="password-input-container">
              <Input
                id="oldPassword"
                type={showPasswords.old ? 'text' : 'password'}
                placeholder="Enter current password"
                value={formData.oldPassword}
                onChange={handleInputChange('oldPassword')}
                className="password-input"
                required
              />
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => togglePasswordVisibility('old')}
                className="password-toggle"
              >
                {showPasswords.old ? <EyeOff size={16} /> : <Eye size={16} />}
              </Button>
            </div>
          </div>

          {/* New Password */}
          <div className="form-field">
            <label htmlFor="newPassword" className="block text-900 font-medium mb-2">
              New Password
            </label>
            <div className="password-input-container">
              <Input
                id="newPassword"
                type={showPasswords.new ? 'text' : 'password'}
                placeholder="Enter new password"
                value={formData.newPassword}
                onChange={handleInputChange('newPassword')}
                className="password-input"
                required
              />
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => togglePasswordVisibility('new')}
                className="password-toggle"
              >
                {showPasswords.new ? <EyeOff size={16} /> : <Eye size={16} />}
              </Button>
            </div>
          </div>

          {/* Confirm Password */}
          <div className="form-field">
            <label htmlFor="confirmPassword" className="block text-900 font-medium mb-2">
              Confirm New Password
            </label>
            <div className="password-input-container">
              <Input
                id="confirmPassword"
                type={showPasswords.confirm ? 'text' : 'password'}
                placeholder="Confirm new password"
                value={formData.confirmPassword}
                onChange={handleInputChange('confirmPassword')}
                className="password-input"
                required
              />
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => togglePasswordVisibility('confirm')}
                className="password-toggle"
              >
                {showPasswords.confirm ? <EyeOff size={16} /> : <Eye size={16} />}
              </Button>
            </div>
          </div>

          {/* Buttons */}
          <div className="modal-buttons">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={isLoading}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isLoading}
              className="update-btn"
            >
              {isLoading ? 'Updating...' : 'Update Password'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default UpdatePasswordModal;