import React, { useState } from 'react';
import UniversityOverview from './UniversityOverview';
import FacultyView from './FacultyView';

type Tab = 'university' | 'faculty';

const AnalyticsDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('university');

  return (
    <div className="analytics-dashboard" style={{ padding: '24px', maxWidth: 1400, margin: '0 auto' }}>
      {/* Page Header */}
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-900">Analytics Dashboard</h2>
        <p className="text-sm text-gray-500 mt-1">Strategic performance insights — mock data for demo</p>
      </div>

      {/* Tab Switcher */}
      <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1 w-fit mb-6">
        <button
          onClick={() => setActiveTab('university')}
          className={`px-5 py-2 rounded-md text-sm font-medium transition-all ${
            activeTab === 'university'
              ? 'bg-white text-gray-900 shadow-sm'
              : 'text-gray-500 hover:text-gray-700'
          }`}
        >
          University Overview
        </button>
        <button
          onClick={() => setActiveTab('faculty')}
          className={`px-5 py-2 rounded-md text-sm font-medium transition-all ${
            activeTab === 'faculty'
              ? 'bg-white text-gray-900 shadow-sm'
              : 'text-gray-500 hover:text-gray-700'
          }`}
        >
          Faculty View
        </button>
      </div>

      {/* Active Tab Content */}
      {activeTab === 'university' ? <UniversityOverview /> : <FacultyView />}
    </div>
  );
};

export default AnalyticsDashboard;
