import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { facultyService } from '../../services/facultyService';
import { Faculty, FacultyFormData } from '../../types';
import { toast } from 'react-hot-toast';
import './FacultyModal.css';

interface FacultyModalProps {
  faculty: Faculty | null;
  isVisible: boolean;
  onClose: () => void;
  onSave: () => void;
}

const FacultyModal: React.FC<FacultyModalProps> = ({ 
  faculty, 
  isVisible, 
  onClose, 
  onSave 
}) => {
  const [formData, setFormData] = useState<FacultyFormData>({
    name: '',
    facultyCode: ''
  });
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});

  useEffect(() => {
    if (isVisible) {
      if (faculty) {
        // Edit mode - populate form with existing data
        setFormData({
          name: faculty.name,
          facultyCode: (faculty as any).facultyCode || ''
        });
      } else {
        // Add mode - reset form
        setFormData({
          name: '',
          facultyCode: ''
        });
      }
      setErrors({});
    }
  }, [faculty, isVisible]);

  const validateForm = (): boolean => {
    const newErrors: { [key: string]: string } = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Faculty name is required';
    }

    if (!formData.facultyCode.trim()) {
      newErrors.facultyCode = 'Faculty code is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: keyof FacultyFormData) => (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
  ) => {
    setFormData(prev => ({
      ...prev,
      [field]: e.target.value
    }));
    
    // Clear error when user starts typing
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: ''
      }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    setIsLoading(true);
    
    try {
      if (faculty) {
        // Edit existing faculty
        await facultyService.updateFaculty(faculty.id, formData);
        toast.success('Faculty updated successfully!');
      } else {
        // Create new faculty
        await facultyService.createFaculty(formData);
        toast.success('Faculty created successfully!');
      }
      
      onSave(); // Refresh parent data and close modal
    } catch (error: any) {
      toast.error(error.message || 'Operation failed');
    } finally {
      setIsLoading(false);
    }
  };

  const handleClose = () => {
    if (!isLoading) {
      onClose();
    }
  };

  // Add body scroll lock
  useEffect(() => {
    if (isVisible) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isVisible]);

  if (!isVisible) return null;

  return createPortal(
    <div className="p-dialog-mask p-component-overlay p-component-overlay-enter" onClick={handleClose}>
        <div className="p-dialog p-component p-dialog-center" onClick={(e) => e.stopPropagation()}>
          <div className="p-dialog-content">
            {/* Modal Header */}
            <div className="p-dialog-header">
              <span className="p-dialog-title">
                {faculty ? 'Edit Faculty' : 'Add Faculty'}
              </span>
              <div className="p-dialog-header-icons">
                <button
                  className="p-dialog-header-icon p-dialog-header-close"
                  type="button"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  <X className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Modal Body */}
            <form onSubmit={handleSubmit} className="faculty-form">
              <div className="p-fluid">
                {/* Faculty Name Field */}
                <div className="field col-12">
                  <label htmlFor="facultyName" className="required-field">
                    Faculty Name
                  </label>
                  <input
                    id="facultyName"
                    type="text"
                    placeholder="Enter faculty name"
                    value={formData.name}
                    onChange={handleInputChange('name')}
                    className={`p-inputtext p-component ${errors.name ? 'p-invalid' : ''}`}
                    disabled={isLoading}
                    required
                  />
                  {errors.name && (
                    <small className="p-error">{errors.name}</small>
                  )}
                </div>

                {/* Faculty Code Field */}
                <div className="field col-12">
                  <label htmlFor="facultyCode" className="required-field">
                    Faculty Code
                  </label>
                  <input
                    id="facultyCode"
                    type="text"
                    placeholder="Enter faculty code (e.g., ENG, SCI)"
                    value={formData.facultyCode}
                    onChange={handleInputChange('facultyCode')}
                    className={`p-inputtext p-component ${errors.facultyCode ? 'p-invalid' : ''}`}
                    disabled={isLoading}
                    required
                    style={{ textTransform: 'uppercase' }}
                  />
                  {errors.facultyCode && (
                    <small className="p-error">{errors.facultyCode}</small>
                  )}
                </div>

              </div>

              {/* Modal Footer */}
              <div className="p-dialog-footer">
                <button
                  type="button"
                  className="p-button p-component p-button-secondary"
                  onClick={handleClose}
                  disabled={isLoading}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="p-button p-component p-button-primary"
                  disabled={isLoading}
                >
                  {isLoading ? (
                    <span className="p-button-loading-icon pi pi-spinner pi-spin"></span>
                  ) : null}
                  {isLoading 
                    ? 'Saving...' 
                    : (faculty ? 'Update Faculty' : 'Create Faculty')
                  }
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>,
    document.body
  );
};

export default FacultyModal;