import axios from 'axios';
import { Faculty, FacultyFormData, ApiResponse, PaginatedResponse } from '../types';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/';

class FacultyService {
  private axiosInstance;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });

    // Request interceptor to add auth token
    this.axiosInstance.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token');
        if (token) {
          config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
      },
      (error) => {
        return Promise.reject(error);
      }
    );

    // Response interceptor for error handling
    this.axiosInstance.interceptors.response.use(
      (response) => response,
      (error) => {
        if (error.response?.status === 401) {
          // Token expired or invalid
          localStorage.removeItem('token');
          localStorage.removeItem('userRole');
          localStorage.removeItem('tokenExpiration');
          window.location.href = '/';
        }
        return Promise.reject(error);
      }
    );
  }

  async getFaculties(page: number = 1, pageSize: number = 10, search: string = ''): Promise<PaginatedResponse<Faculty>> {
    try {
      const params = new URLSearchParams({
        page: page.toString(),
        pageSize: pageSize.toString(),
        ...(search && { search })
      });

      const response = await this.axiosInstance.get(`/api/faculty?${params.toString()}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to fetch faculties');
    }
  }

  async getFacultyById(id: string): Promise<ApiResponse<Faculty>> {
    try {
      const response = await this.axiosInstance.get(`/api/faculty/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch faculty');
    }
  }

  async createFaculty(facultyData: FacultyFormData): Promise<ApiResponse<Faculty>> {
    try {
      const response = await this.axiosInstance.post('/api/faculty', facultyData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      } else if (error.response?.data?.message) {
        throw new Error(error.response.data.message);
      }
      throw new Error('Failed to create faculty');
    }
  }

  async updateFaculty(id: string, facultyData: FacultyFormData): Promise<ApiResponse<Faculty>> {
    try {
      const response = await this.axiosInstance.put(`/api/faculty/${id}`, facultyData);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to update faculty');
    }
  }

  async deleteFaculty(id: string): Promise<ApiResponse<any>> {
    try {
      const response = await this.axiosInstance.delete(`/api/faculty/${id}`);
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to delete faculty');
    }
  }

  // Get all faculties without pagination (for dropdowns)
  async getAllFaculties(): Promise<ApiResponse<Faculty[]>> {
    try {
      const response = await this.axiosInstance.get('/api/faculty');
      return response.data;
    } catch (error: any) {
      if (error.response?.data?.Message) {
        throw new Error(error.response.data.Message);
      }
      throw new Error('Failed to fetch all faculties');
    }
  }
}

export const facultyService = new FacultyService();