import React, { useState, useEffect } from 'react';
import { Outlet, useNavigate } from 'react-router-dom';
import { X, Info, User, Users, Settings, Star, RefreshCw, Edit2 } from 'lucide-react';
import Header from '../header/Header';
import './AdminLayout.css';

interface MenuItem {
  path: string;
  label: string;
  icon: React.ReactNode;
  roles: string[];
}

const AdminLayout: React.FC = () => {
  const [sidebarVisible, setSidebarVisible] = useState(false);
  const [isDean, setIsDean] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    // Check user role from localStorage
    const userRole = localStorage.getItem('userRole');
    setIsDean(userRole === 'Dean');
  }, []);

  const menuItems: MenuItem[] = [
    {
      path: 'categories',
      label: 'Pillars',
      icon: <Info className="mr-2" />,
      roles: ['Admin']
    },
    {
      path: 'faculties',
      label: 'Faculties',
      icon: <User className="mr-2" />,
      roles: ['Admin']
    },
    {
      path: 'departments',
      label: 'Departments',
      icon: <Users className="mr-2" />,
      roles: ['Admin', 'Dean']
    },
    {
      path: 'user',
      label: 'Users',
      icon: <Users className="mr-2" />,
      roles: ['Admin']
    },
    {
      path: 'parameters',
      label: 'Parameters',
      icon: <Settings className="mr-2" />,
      roles: ['Admin']
    },
    {
      path: 'cycles',
      label: 'Cycles',
      icon: <RefreshCw className="mr-2" />,
      roles: ['Admin']
    },
    {
      path: 'ratings-report',
      label: 'Yearly Ratings Report',
      icon: <Star className="mr-2" />,
      roles: ['Admin', 'Dean']
    },
    {
      path: 'edit-requests',
      label: 'Edit Requests',
      icon: <Edit2 className="mr-2" />,
      roles: ['Admin']
    }
  ];

  const handleMenuToggle = () => {
    setSidebarVisible(true);
  };

  const handleNavigation = (path: string) => {
    navigate(`/admin/${path}`);
    setSidebarVisible(false);
  };

  const closeSidebar = () => {
    setSidebarVisible(false);
  };

  // Filter menu items based on user role
  const filteredMenuItems = menuItems.filter(item => 
    isDean ? item.roles.includes('Dean') : item.roles.includes('Admin')
  );

  return (
    <>
      <Header showMenu={true} onMenuToggle={handleMenuToggle} />
      
      {/* Sidebar - Exact PrimeNG p-sidebar replication */}
      {sidebarVisible && (
        <>
          {/* Backdrop */}
          <div 
            className="sidebar-backdrop" 
            onClick={closeSidebar}
          ></div>
          
          {/* Sidebar */}
          <div className="p-sidebar p-sidebar-left p-sidebar-visible">
            <div className="p-sidebar-content">
              <div className="flex flex-column h-full">
                {/* Sidebar Header - EXACT Angular structure */}
                <div className="flex align-items-center justify-content-between px-4 pt-3 flex-shrink-0">
                  <span className="inline-flex align-items-center gap-2">
                    <span className="font-semibold text-2xl text-primary">
                      NED University
                    </span>
                  </span>
                  <span>
                    <button
                      className="p-button p-button-icon-only p-button-rounded p-button-outlined"
                      onClick={closeSidebar}
                      style={{ height: '2rem', width: '2rem' }}
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </span>
                </div>
                
                {/* Sidebar Navigation - EXACT Angular structure */}
                <div className="overflow-y-auto">
                  <ul className="list-none p-3 m-0">
                    <li>
                      <ul className="list-none p-0 m-0 overflow-hidden">
                        {filteredMenuItems.map((item) => (
                          <li key={item.path}>
                            <button
                              onClick={() => handleNavigation(item.path)}
                              className="flex align-items-center cursor-pointer p-3 border-round text-700 hover:surface-100 transition-duration-150 transition-colors p-ripple sidebar-nav-button"
                            >
                              {item.icon}
                              <span className="font-medium">{item.label}</span>
                            </button>
                          </li>
                        ))}
                      </ul>
                    </li>
                  </ul>
                </div>
              </div>
            </div>
          </div>
        </>
      )}

      {/* Main Content */}
      <main className="admin-main-content">
        <Outlet />
      </main>
    </>
  );
};

export default AdminLayout;