import { authService } from './authService';

export interface DashboardCategory {
  id: string;
  _id: string;
  name: string;
  description?: string;
  sortOrder: number;
  parameterCount: number;
  submittedCount: number;
  createdAt: string;
  updatedAt: string;
}

export interface DashboardStatistics {
  categories: DashboardCategory[];
  overall: {
    totalParameters: number;
    totalSubmitted: number;
    progressPercentage: number;
  };
}

export interface DashboardOverview {
  totalCategories: number;
  totalParameters: number;
  userSubmissions: number;
  completionRate: number;
}

class DashboardService {
  // Get dashboard statistics with parameter counts per category
  async getDashboardStatistics(): Promise<DashboardStatistics> {
    try {
      const response = await authService.axiosInstance.get('/api/dashboard/statistics');
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch dashboard statistics');
    }
  }

  // Get dashboard overview
  async getDashboardOverview(): Promise<DashboardOverview> {
    try {
      const response = await authService.axiosInstance.get('/api/dashboard/overview');
      return response.data.Data;
    } catch (error: any) {
      throw new Error(error.response?.data?.Message || 'Failed to fetch dashboard overview');
    }
  }
}

export const dashboardService = new DashboardService();